// No PLAYED_FOR relationship is defined in the schema, so we can only return clubs founded in 1892.
MATCH (c:Club)
WHERE toInteger(c.inception_year) = 1892
RETURN DISTINCT c.name;

MATCH (p:Player {name: "Laurent Blanc"})-[:PLAYED_FOR]->(c:Club)
OPTIONAL MATCH (c)-[:hasHomeVenue]->(v:Venue)
RETURN count(DISTINCT v) AS venueCount;

// The schema does not define a relationship between Player and Club, so we cannot directly retrieve players who have played for a club that used WakeMed Soccer Park as its home venue.
